fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Ensure the tolerance is strictly positive
    if tol <= 0 {
        panic!("Tolerance must be strictly positive");
    }
    // Calculate the absolute difference
    (a - b).abs() < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Ensure the tolerance is strictly positive
    if tol <= 0 {
        panic!("Tolerance must be strictly positive");
    }
    // Ensure the input vectors are of the same length
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");
    
    // Create a result vector to store the boolean results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through the elements of both vectors
    for (&x, &y) in a.iter().zip(b.iter()) {
        result.push(is_close_i8(x, y, tol));
    }
    
    result
}